style.css:
@-moz-document url("https://scratch.mit.edu/projects/396299334/fullscreen/") {
[class^="stage-wrapper_stage-wrapper_"] {
      background-color: #a4b7b7;
      border-radius: 0px;
      top: 1.5rem;
    }

    canvas {
       border: 5px solid #656565;
    }


    [class^="stage_stage_1fD7k.stage_full-screen_"] {
      border: 0;
      border-radius: 0px;
    }

    [class^="stage-header_stage-header-wrapper-overlay_"],
    #navigation,
    #footer,
    .project-lower-container {
      background-color: #a4b7b7;
      display: none !important;
    }

    [class^="stage-wrapper_stage-wrapper_"] [class^="stage-wrapper_full-screen_"] {
      top: -2px;
      width: 100%;
      height: 100%;
    }

    [class^="question_question-submit-button_"] {
      background: hsl(180deg 100% 40%);
    }

    html,
    body {
      background-color: #a4b7b7;
    }

    [class^="input_input-form_"]:hover {
      border-color: hsla(215, 100%, 65%, 1);
    }

    [class^="monitor_monitor-container_"] {
      background: #a4b7b7;
      border: 1px solid hsla(0, 0%, 0%, 0.15);
      border-radius: calc(0.5rem / 2);
    }

    [class^="monitor_large-value_"] {
      padding: 0rem !important;
      font-family: 'Pixel' !important;
      font-size: 12px !important;
      color: black !important;
      background: rgb(0 204 204) !important;
      border-radius: 0 !important;
    }

    [class^="monitor_monitor-container_"] {
      background: #a4b7b7 !important;
      border: 1px solid hsla(0, 0%, 0%, 0.15) !important;
      border-radius: 0 !important;
    }
}
